//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ _ЗначенияНастроекСостава.Клиент КАК Клиент, _ЗначенияНастроекСостава.ВидДоговора КАК ВидДоговора, _ЗначенияНастроекСостава.Договор КАК Договор, _ЗначенияНастроекСостава.Отчет КАК Отчет, _ЗначенияНастроекСостава.Периодичность КАК Периодичность, _ДанныеРегистра.Настройка КАК Настройка, _ДанныеРегистра.Значение КАК Значение, _ДанныеРегистра.Период КАК Период, _ДанныеРегистра.Приоритет КАК Приоритет, _ДанныеРегистра.КодНастройки КАК КодНастройки ПОМЕСТИТЬ _НастройкиАвтоматизации ИЗ _ЗначенияНастроекСостава КАК _ЗначенияНастроекСостава ЛЕВОЕ СОЕДИНЕНИЕ _ДанныеРегистра КАК _ДанныеРегистра ПО (_ДанныеРегистра.Настройка <> ЗНАЧЕНИЕ(ПланВидовХарактеристик.НастройкиОтчетов.Формировать)) И (ВЫБОР КОГДА _ДанныеРегистра.Субъект = НЕОПРЕДЕЛЕНО ТОГДА ИСТИНА КОГДА ТИПЗНАЧЕНИЯ(_ДанныеРегистра.Субъект) = ТИП(Справочник.СчетаДоверительногоУправления) ТОГДА _ДанныеРегистра.Субъект = _ЗначенияНастроекСостава.Договор КОГДА ТИПЗНАЧЕНИЯ(_ДанныеРегистра.Субъект) <> ТИП(Справочник.СчетаДоверительногоУправления) И _ДанныеРегистра.ВидДоговора <> ЗНАЧЕНИЕ(Перечисление.ВидыДоговоровДоверительногоУправления.ПустаяСсылка) ТОГДА _ДанныеРегистра.Субъект = _ЗначенияНастроекСостава.Клиент И _ДанныеРегистра.ВидДоговора = _ЗначенияНастроекСостава.ВидДоговора КОГДА ТИПЗНАЧЕНИЯ(_ДанныеРегистра.Субъект) <> ТИП(Справочник.СчетаДоверительногоУправления) И _ДанныеРегистра.ВидДоговора = ЗНАЧЕНИЕ(Перечисление.ВидыДоговоровДоверительногоУправления.ПустаяСсылка) ТОГДА _ДанныеРегистра.Субъект = _ЗначенияНастроекСостава.Клиент КОНЕЦ) И (ВЫБОР КОГДА _ДанныеРегистра.Отчет = ЗНАЧЕНИЕ(Справочник.Отчеты.ПустаяСсылка) ТОГДА ИСТИНА КОГДА _ДанныеРегистра.Отчет.ЭтоГруппа ТОГДА _ДанныеРегистра.Отчет = _ЗначенияНастроекСостава.ГруппаОтчетов ИНАЧЕ _ДанныеРегистра.Отчет = _ЗначенияНастроекСостава.Отчет КОНЕЦ) И (ВЫБОР КОГДА _ДанныеРегистра.Периодичность = ЗНАЧЕНИЕ(Перечисление.ПериодичностьПредоставленияОтчетности.ПустаяСсылка) ТОГДА ИСТИНА ИНАЧЕ _ДанныеРегистра.Периодичность = _ЗначенияНастроекСостава.Периодичность КОНЕЦ) ;
